function terminalFailed(model) {
    const { exitCode, signal, running } = model.card;
    return running !== true && ((exitCode !== undefined && exitCode !== 0) || signal !== undefined);
}

function terminalExitLabel(model, t) {
    if (model == null || model.card.background || !terminalFailed(model))
        return null;
    const { exitCode, signal } = model.card;
    if (signal !== undefined)
        return t('terminal.signal', { signal });
    if (exitCode == null)
        return t('terminal.noExitCode');
    return t('terminal.exitCode', { code: exitCode });
}

function localizeTerminalCardModel(model, t) {
    if (model.copy.kind === 'shell') {
        return {
            card: { command: model.copy.command, ...model.card },
            description: model.copy.description,
        };
    }
    return {
        card: {
            command: model.copy.text === '' ? t('terminal.sendInput') : model.copy.text,
            ...model.card,
        },
        description: t('terminal.session', { sessionId: model.copy.sessionId }),
    };
}

function parseExitStatus(text) {
    const signal = /\n\[killed by signal: ([^\]\n]+)\]$/.exec(text);
    if (signal?.[1] !== undefined)
        return { output: text.slice(0, signal.index), signal: signal[1] };
    const exit = /\n\[exit code: (-?\d+|null)\]$/.exec(text);
    if (exit?.[1] !== undefined)
        return { output: text.slice(0, exit.index), exitCode: exit[1] === 'null' ? null : Number(exit[1]) };
    return { output: text, exitCode: 0 };
}
